-- Quiz CRPE : « sciences et technologie » est séparé en trois matières (SVT, physique-chimie, technologie).
alter table public.quiz_questions drop constraint quiz_questions_matiere_check;

-- Reclassement des 10 questions existantes (SVT ou physique-chimie)
update public.quiz_questions set matiere = 'svt'
  where matiere = 'sciences_technologie' and (question like 'Quel gaz les végétaux chlorophylliens%' or question like 'Dans quel organe se fait%'
    or question like 'Dans une chaîne alimentaire%' or question like 'À quel groupe d''animaux appartient la baleine%');
update public.quiz_questions set matiere = 'physique_chimie' where matiere = 'sciences_technologie';
update public.quiz_questions q set ordre = r.n
  from (select id, row_number() over (partition by matiere order by ordre) as n from public.quiz_questions where matiere in ('svt','physique_chimie')) r
  where q.id = r.id;

alter table public.quiz_questions add constraint quiz_questions_matiere_check check (matiere in
  ('francais','mathematiques','histoire_geographie','emc','svt','physique_chimie','technologie','arts','anglais'));

-- 20 nouvelles questions : 6 en SVT, 4 en physique-chimie, 10 en technologie (10 par matière au total)
