insert into public.quiz_questions (matiere, ordre, question, choix, reponse, explication) values
  ('svt', 5, 'Quelle molécule porte l''information génétique ?', '["Le glucose", "L''ADN", "L''hémoglobine", "L''amidon"]'::jsonb, 'L''ADN', 'L''ADN, contenu dans les chromosomes du noyau des cellules, porte les gènes : c''est le support de l''information génétique transmise d''une génération à l''autre.'),
  ('svt', 6, 'Combien de chromosomes contient une cellule humaine, hors cellules reproductrices ?', '["23", "32", "46", "64"]'::jsonb, '46', 'Les cellules du corps humain contiennent 46 chromosomes, soit 23 paires. Les cellules reproductrices (gamètes) n''en contiennent que 23, un de chaque paire.'),
  ('svt', 7, 'Quel organe produit l''insuline ?', '["Le foie", "Le pancréas", "L''estomac", "Les reins"]'::jsonb, 'Le pancréas', 'Le pancréas libère l''insuline dans le sang quand la glycémie augmente : cette hormone fait baisser le taux de sucre dans le sang.'),
  ('svt', 8, 'Quelle est l''origine d''un séisme ?', '["Une rupture brutale des roches en profondeur", "Une éruption de lave en surface", "L''attraction de la Lune sur les océans", "Des vents très violents"]'::jsonb, 'Une rupture brutale des roches en profondeur', 'Les roches soumises à des contraintes, souvent aux limites des plaques tectoniques, finissent par casser brutalement : l''énergie libérée se propage sous forme d''ondes sismiques.'),
  ('svt', 9, 'Quel est le rôle principal des globules blancs ?', '["Transporter le dioxygène", "Assurer la coagulation du sang", "Défendre l''organisme contre les micro-organismes", "Digérer les aliments"]'::jsonb, 'Défendre l''organisme contre les micro-organismes', 'Les globules blancs participent aux défenses immunitaires. Le transport du dioxygène est assuré par les globules rouges, la coagulation par les plaquettes.'),
  ('svt', 10, 'Quel élément est présent dans toutes les cellules vivantes ?', '["Un noyau", "Une paroi", "Une membrane", "Des chloroplastes"]'::jsonb, 'Une membrane', 'Toute cellule est délimitée par une membrane. La paroi et les chloroplastes n''existent que chez certaines cellules (végétales notamment), et les bactéries n''ont pas de noyau.'),
  ('physique_chimie', 7, 'Quelle est la formule chimique de l''eau ?', '["HO₂", "H₂O", "H₂O₂", "CO₂"]'::jsonb, 'H₂O', 'Une molécule d''eau est formée de deux atomes d''hydrogène et d''un atome d''oxygène : H₂O. H₂O₂ est l''eau oxygénée, CO₂ le dioxyde de carbone.'),
  ('physique_chimie', 8, 'Quelle est l''unité de la tension électrique ?', '["L''ampère", "Le watt", "Le volt", "L''ohm"]'::jsonb, 'Le volt', 'La tension se mesure en volts (V) avec un voltmètre branché en dérivation. L''ampère mesure l''intensité, le watt la puissance et l''ohm la résistance.'),
  ('physique_chimie', 9, 'Quelle est la vitesse de la lumière dans le vide, environ ?', '["340 m/s", "300 km/h", "300 000 km/s", "3 000 000 km/s"]'::jsonb, '300 000 km/s', 'La lumière se propage dans le vide à environ 300 000 km/s. 340 m/s est la vitesse du son dans l''air : c''est pourquoi on voit l''éclair avant d''entendre le tonnerre.'),
  ('physique_chimie', 10, 'Lequel de ces phénomènes est une transformation chimique ?', '["La fonte d''un glaçon", "La dissolution du sucre dans l''eau", "La combustion du bois", "L''évaporation de l''eau"]'::jsonb, 'La combustion du bois', 'Une transformation chimique produit de nouvelles espèces chimiques : la combustion du bois donne du dioxyde de carbone, de l''eau et des cendres. Les trois autres sont des transformations physiques, qui ne créent pas de nouvelle substance.'),
  ('technologie', 1, 'Dans un programme Scratch, à quoi sert une boucle « répéter 4 fois » ?', '["À arrêter le programme", "À exécuter plusieurs fois les mêmes instructions", "À tester une condition une seule fois", "À créer une variable"]'::jsonb, 'À exécuter plusieurs fois les mêmes instructions', 'Une boucle répète un bloc d''instructions : par exemple « avancer de 100, tourner de 90° » répété 4 fois trace un carré, sans écrire quatre fois les mêmes blocs.'),
  ('technologie', 2, 'Dans un objet technique, quel est le rôle d''un capteur ?', '["Produire un mouvement", "Acquérir une information", "Stocker de l''énergie", "Afficher un résultat"]'::jsonb, 'Acquérir une information', 'Un capteur mesure une grandeur (température, luminosité, présence…) et la transmet au système. Les actionneurs, eux, agissent (moteur, lampe, haut-parleur).'),
  ('technologie', 3, 'Lequel de ces composants est un actionneur ?', '["Un moteur", "Un capteur de luminosité", "Un thermomètre", "Un détecteur de présence"]'::jsonb, 'Un moteur', 'Un actionneur transforme un ordre en action : le moteur produit un mouvement. Les trois autres composants sont des capteurs, qui recueillent des informations.'),
  ('technologie', 4, 'Que définit le cahier des charges d''un objet technique ?', '["Son prix de vente en magasin", "Les besoins et contraintes auxquels il doit répondre", "La liste de ses acheteurs", "Son mode de recyclage uniquement"]'::jsonb, 'Les besoins et contraintes auxquels il doit répondre', 'Le cahier des charges décrit les fonctions attendues de l''objet et les contraintes à respecter (dimensions, coût, sécurité, environnement…) avant sa conception.'),
  ('technologie', 5, 'Lequel de ces matériaux est un bon isolant thermique ?', '["Le cuivre", "L''acier", "L''aluminium", "Le polystyrène expansé"]'::jsonb, 'Le polystyrène expansé', 'Le polystyrène expansé emprisonne de l''air, mauvais conducteur de la chaleur : il isole bien. Les métaux comme le cuivre, l''acier et l''aluminium conduisent bien la chaleur.'),
  ('technologie', 6, 'Combien de bits contient un octet ?', '["2", "4", "8", "10"]'::jsonb, '8', 'Un octet est formé de 8 bits, chaque bit valant 0 ou 1 : un octet peut donc prendre 2⁸ = 256 valeurs différentes.'),
  ('technologie', 7, 'Qu''étudie l''analyse du cycle de vie d''un objet ?', '["Uniquement sa durée d''utilisation", "Ses impacts sur l''environnement, de l''extraction des matières premières à sa fin de vie", "Son évolution esthétique au fil des années", "Le nombre de ses utilisateurs"]'::jsonb, 'Ses impacts sur l''environnement, de l''extraction des matières premières à sa fin de vie', 'L''analyse du cycle de vie évalue les impacts environnementaux à chaque étape : extraction des matériaux, fabrication, transport, utilisation, puis recyclage ou élimination.'),
  ('technologie', 8, 'À quoi sert une adresse IP ?', '["À identifier un appareil sur un réseau", "À protéger un ordinateur des virus", "À mesurer le débit de la connexion", "À stocker des fichiers"]'::jsonb, 'À identifier un appareil sur un réseau', 'L''adresse IP identifie chaque appareil connecté à un réseau, comme une adresse postale : elle permet d''acheminer les données vers le bon destinataire.'),
  ('technologie', 9, 'Une petite roue dentée entraîne une grande roue dentée. Comment tourne la grande roue ?', '["Plus vite que la petite", "Plus lentement que la petite", "À la même vitesse", "Elle ne tourne pas"]'::jsonb, 'Plus lentement que la petite', 'À chaque tour de la petite roue, la grande ne fait qu''une partie de tour, car elle a plus de dents : elle tourne plus lentement (et en sens inverse).'),
  ('technologie', 10, 'Dans un programme, à quoi sert une variable ?', '["À stocker une valeur qui peut changer pendant le programme", "À dessiner une figure", "À répéter des instructions", "À arrêter le programme"]'::jsonb, 'À stocker une valeur qui peut changer pendant le programme', 'Une variable est une « boîte » nommée qui garde une valeur, par exemple un score, et que le programme peut lire et modifier au fil de son exécution.');
